code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] > 1]
    dist = [[None] * w for _ in range(h)]
    owner = [[None] * w for _ in range(h)]
    q = deque()
    for r, c, color in markers:
        dist[r][c] = 0
        owner[r][c] = color
        q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0:
                nd = dist[r][c] + 1
                if dist[nr][nc] is None:
                    dist[nr][nc] = nd
                    owner[nr][nc] = owner[r][c]
                    q.append((nr, nc))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or owner[r][c] is not None or (r,c) in seen:
                continue
            comp = [(r,c)]
            seen.add((r,c))
            for x,y in comp:
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 0 and (nx,ny) not in seen:
                        seen.add((nx,ny)); comp.append((nx,ny))
            if markers:
                color = min(markers, key=lambda m: min(abs(x-m[0])+abs(y-m[1]) for x,y in comp))[2]
                for x,y in comp:
                    owner[x][y] = color
    for r in range(1, h-1):
        for c in range(1, w-1):
            if all(grid[rr][cc] != 0 for rr in range(r-1,r+2) for cc in range(c-1,c+2)) and owner[r][c] is not None:
                out[r][c] = owner[r][c]
    return out
'''
